package com.parevetimer.app;
import android.app.PendingIntent;import android.appwidget.*;import android.content.*;import android.os.SystemClock;import android.widget.RemoteViews;
public class TimerWidgetProvider extends AppWidgetProvider{private static final String B="com.parevetimer.app.ACTION_WIDGET_BEEF",D="com.parevetimer.app.ACTION_WIDGET_DAIRY";@Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){update(c,m,ids);}@Override public void onReceive(Context c,Intent i){super.onReceive(c,i);if(B.equals(i.getAction())){TimerManager.start(c,TimerManager.BEEF);update(c,AppWidgetManager.getInstance(c),null);}else if(D.equals(i.getAction())){TimerManager.start(c,TimerManager.DAIRY);update(c,AppWidgetManager.getInstance(c),null);}}private static void update(Context c,AppWidgetManager m,int[] ids){if(ids==null)ids=m.getAppWidgetIds(new ComponentName(c,TimerWidgetProvider.class));boolean a=TimerManager.isActive(c);long remain=Math.max(0,Prefs.get(c).getLong(Prefs.END,0)-System.currentTimeMillis());for(int id:ids){RemoteViews r=new RemoteViews(c.getPackageName(),R.layout.widget_timer);r.setOnClickPendingIntent(R.id.widget_beef,pi(c,B,101));r.setOnClickPendingIntent(R.id.widget_dairy,pi(c,D,102));r.setViewVisibility(R.id.widget_chronometer,a?0:8);r.setViewVisibility(R.id.widget_status,a?8:0);if(a){r.setTextViewText(R.id.widget_title,TimerManager.BEEF.equals(Prefs.get(c).getString(Prefs.CATEGORY,""))?"טיימר בשרי":"טיימר חלבי");r.setChronometer(R.id.widget_chronometer,SystemClock.elapsedRealtime()+remain,null,true);}else{r.setTextViewText(R.id.widget_title,"אני פרווה!");r.setTextViewText(R.id.widget_status,"אני פרווה!");}m.updateAppWidget(id,r);}}private static PendingIntent pi(Context c,String a,int req){return PendingIntent.getBroadcast(c,req,new Intent(c,TimerWidgetProvider.class).setAction(a),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}}
